/*
 * omx_clap_static.c — the table of libomxplugins.a: every shipped plugin's face entry by CLAP id,
 * the test plugins' in a table of their own, and the one entry over all of them
 * (include/omx_clap_static.h). The rows are generated by
 * tools/gen.mjs from the declarations; a face missing from the archive is an unresolved symbol at
 * link time, never a runtime refusal.
 */
#include <stddef.h>
#include <string.h>

#include <clap/factory/plugin-factory.h>

#include "omx_clap_static.h"

const struct omx_clap_static_plugin OMX_CLAP_STATIC_PLUGINS[] = {
    /* BEGIN GENERATED clap-table: tools/gen.mjs, one row per shipped plugin */
    {"org.openmixer.chorus", &omx_clap_entry_chorus},
    {"org.openmixer.comp", &omx_clap_entry_comp},
    {"org.openmixer.deesser", &omx_clap_entry_deesser},
    {"org.openmixer.delay", &omx_clap_entry_delay},
    {"org.openmixer.drive", &omx_clap_entry_drive},
    {"org.openmixer.dyneq", &omx_clap_entry_dyneq},
    {"org.openmixer.eq8", &omx_clap_entry_eq8},
    {"org.openmixer.eq16", &omx_clap_entry_eq16},
    {"org.openmixer.eq32", &omx_clap_entry_eq32},
    {"org.openmixer.flanger", &omx_clap_entry_flanger},
    {"org.openmixer.geq", &omx_clap_entry_geq},
    {"org.openmixer.keyed-gate", &omx_clap_entry_gate},
    {"org.openmixer.limiter", &omx_clap_entry_limiter},
    {"org.openmixer.multiband", &omx_clap_entry_mbcomp},
    {"org.openmixer.phaser", &omx_clap_entry_phaser},
    {"org.openmixer.pitch", &omx_clap_entry_pitch},
    {"org.openmixer.reverb", &omx_clap_entry_reverb},
    {"org.openmixer.rotary", &omx_clap_entry_rotary},
    {"org.openmixer.strip", &omx_clap_entry_strip},
    {"org.openmixer.transient", &omx_clap_entry_transient},
    {"org.openmixer.tremolo", &omx_clap_entry_tremolo},
    /* END GENERATED clap-table */
};

const uint32_t OMX_CLAP_STATIC_COUNT = (uint32_t)(sizeof OMX_CLAP_STATIC_PLUGINS / sizeof OMX_CLAP_STATIC_PLUGINS[0]);

/* The test plugins. A sentinel row ends the list, so the table compiles while none is declared; the
 * count leaves it out. */
const struct omx_clap_static_plugin OMX_CLAP_STATIC_TEST_PLUGINS[] = {
    /* BEGIN GENERATED clap-test-table: tools/gen.mjs, one row per test plugin */
    {"org.openmixer.test-note-echo", &omx_clap_entry_test_note_echo},
    {"org.openmixer.test-sine-voice", &omx_clap_entry_test_sine_voice},
    {"org.openmixer.test-transport-probe", &omx_clap_entry_test_transport_probe},
    /* END GENERATED clap-test-table */
    {NULL, NULL},
};

const uint32_t OMX_CLAP_STATIC_TEST_COUNT = (uint32_t)(sizeof OMX_CLAP_STATIC_TEST_PLUGINS / sizeof OMX_CLAP_STATIC_TEST_PLUGINS[0]) - 1u;

const clap_plugin_entry_t *omx_clap_static_find(const char *id) {
  if (!id) return NULL;
  for (uint32_t i = 0; i < OMX_CLAP_STATIC_COUNT; ++i)
    if (strcmp(OMX_CLAP_STATIC_PLUGINS[i].id, id) == 0) return OMX_CLAP_STATIC_PLUGINS[i].entry;
  for (uint32_t i = 0; i < OMX_CLAP_STATIC_TEST_COUNT; ++i)
    if (strcmp(OMX_CLAP_STATIC_TEST_PLUGINS[i].id, id) == 0) return OMX_CLAP_STATIC_TEST_PLUGINS[i].entry;
  return NULL;
}

/* ---- every face behind one entry ---------------------------------------------------------- */

static const clap_plugin_factory_t *face_factory(const clap_plugin_entry_t *e) {
  return (const clap_plugin_factory_t *)e->get_factory(CLAP_PLUGIN_FACTORY_ID);
}

static uint32_t all_count(const clap_plugin_factory_t *f) {
  (void)f;
  return OMX_CLAP_STATIC_COUNT;
}

/* Each face's factory holds one plugin: row i's descriptor is its descriptor 0. */
static const clap_plugin_descriptor_t *all_desc(const clap_plugin_factory_t *f, uint32_t i) {
  (void)f;
  if (i >= OMX_CLAP_STATIC_COUNT) return NULL;
  const clap_plugin_factory_t *ff = face_factory(OMX_CLAP_STATIC_PLUGINS[i].entry);
  return ff ? ff->get_plugin_descriptor(ff, 0) : NULL;
}

static const clap_plugin_t *all_create(const clap_plugin_factory_t *f, const clap_host_t *host, const char *id) {
  (void)f;
  const clap_plugin_entry_t *e = omx_clap_static_find(id);
  const clap_plugin_factory_t *ff = e ? face_factory(e) : NULL;
  return ff ? ff->create_plugin(ff, host, id) : NULL;
}

static const clap_plugin_factory_t ALL_FACTORY = {all_count, all_desc, all_create};

/* Row i of the shipped table, then of the test table: every face the archive links. */
static const clap_plugin_entry_t *linked(uint32_t i) {
  return i < OMX_CLAP_STATIC_COUNT ? OMX_CLAP_STATIC_PLUGINS[i].entry : OMX_CLAP_STATIC_TEST_PLUGINS[i - OMX_CLAP_STATIC_COUNT].entry;
}

/* Every linked face is initialised, the test plugins' too: create_plugin() opens them by id. */
static bool all_init(const char *path) {
  const uint32_t n = OMX_CLAP_STATIC_COUNT + OMX_CLAP_STATIC_TEST_COUNT;
  for (uint32_t i = 0; i < n; ++i) {
    if (linked(i)->init(path)) continue;
    while (i-- > 0) linked(i)->deinit();
    return false;
  }
  return true;
}

static void all_deinit(void) {
  for (uint32_t i = OMX_CLAP_STATIC_COUNT + OMX_CLAP_STATIC_TEST_COUNT; i-- > 0;) linked(i)->deinit();
}

static const void *all_factory(const char *id) {
  return id && strcmp(id, CLAP_PLUGIN_FACTORY_ID) == 0 ? &ALL_FACTORY : NULL;
}

const clap_plugin_entry_t omx_clap_static_entry = {CLAP_VERSION_INIT, all_init, all_deinit, all_factory};
